function validate([word, ch]) {
  if (word.length < 1 || word.length > 250) return 'word needs 1 to 250 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses only lowercase English letters.';
  if (!/^[a-z]$/.test(ch)) return 'ch is one lowercase English letter.';
  return null;
}

