function generate(rand, size) {
  const alphabet = size === 'large' || rand() < 0.3 ? 'abcdefghijklmnopqrstuvwxyz' : 'abcd';
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const n = size === 'large' ? 250 : 1 + Math.floor(rand() * 8);
  const word = Array.from({ length: n }, letter).join('');
  // Mostly pick a letter from the word so a reversal happens; sometimes pick any letter.
  const ch = rand() < 0.75 ? word[Math.floor(rand() * n)] : 'abcdefghijklmnopqrstuvwxyz'[Math.floor(rand() * 26)];
  return [word, ch];
}
